// Release generated by scripts/build-tideline.mjs after every change to the game.
const assets=/* ASSET_HASHES */ {};
const scope=self.registration.scope;
const prefix='tideline:'+new URL(scope).pathname+':';
const current=prefix+'__RELEASE__';
const shell=new URL('index.html',scope).href;
const urls=new Set(Object.keys(assets).map(name=>new URL(name,scope).href));

self.addEventListener('install',event=>{
  event.waitUntil((async()=>{
    const cache=await caches.open(current);
    const requests=Object.entries(assets).map(([name,hash])=>new Request(new URL(name,scope),{
      cache:'reload',credentials:'same-origin',integrity:'sha256-'+hash,
    }));
    await cache.addAll(requests);
  })());
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    for(const key of await caches.keys()) if(key.startsWith(prefix) && key!==current) await caches.delete(key);
    await self.clients.claim();
  })());
});
self.addEventListener('message',event=>{if(event.data==='ACTIVATE')event.waitUntil(self.skipWaiting());});
self.addEventListener('fetch',event=>{
  const request=event.request;if(request.method!=='GET')return;
  const url=new URL(request.url);
  const page=request.mode==='navigate' && (url.origin+url.pathname===scope || url.origin+url.pathname===shell);
  if(!page && !urls.has(url.href))return;
  event.respondWith((async()=>{
    const cache=await caches.open(current);
    return await cache.match(page?shell:url.href) || fetch(request);
  })());
});
